import tarfile
import os

def extract_member(tar_path, member_name, destination):
    '''
Haal 'n spesifieke lid uit 'n tar-argief.

Die funksie kontroleer of die lidnaam met 'n skuinsstreep begin om absolute paaie te voorkom.
    '''
    if member_name.startswith('/'):
        raise ValueError("Lidnaam mag nie met 'n skuinsstreep begin nie om absolute paaie te voorkom.")

    os.makedirs(destination, exist_ok=True)

    try:
        with tarfile.open(tar_path, 'r') as tar:
            # Check if the member exists in the archive
            try:
                tar.getmember(member_name)
            except KeyError:
                raise FileNotFoundError(f"Lid '{member_name}' is nie in die argief '{tar_path}' gevind nie.")

            tar.extract(member_name, path=destination)
            return os.path.join(destination, member_name)
    except tarfile.ReadError as e:
        raise IOError(f"Fout by die lees van die tar-argief '{tar_path}': {e}")

