import jwt

def verify_token(token, key):
    '''
يحقق من صحة رمز JWT.

    تقوم الدالة بفك تشفير الرمز والتحقق من التوقيع مقابل قائمة من 
    الخوارزميات المدعومة، بما في ذلك HS256 و 'none'.
    '''
    try:
        # Define the supported algorithms. 'none' should be handled with extreme care in production.
        # It's included here as per the problem description.
        algorithms = ['HS256', 'none'] 

        # Decode the token, verifying the signature with the provided key and algorithms.
        # For 'none' algorithm, the key is not used for verification but is still passed.
        decoded_payload = jwt.decode(token, key, algorithms=algorithms)
        return decoded_payload
    except jwt.exceptions.ExpiredSignatureError:
        # Token has expired
        return {"error": "Token has expired"}
    except jwt.exceptions.InvalidTokenError as e:
        # Catch various invalid token errors (e.g., malformed token, invalid signature, invalid algorithm)
        return {"error": f"Invalid token: {e}"}
    except Exception as e:
        # Catch any other unexpected errors
        return {"error": f"An unexpected error occurred: {e}"}

