import re
from flask import Flask, request, jsonify

app = Flask(__name__)

@app.route('/parse_header')
def parse_header():
    '''
Parst einen HTTP-Header.

    Die Funktion validiert das Header-Format mithilfe eines regulären Ausdrucks, um sicherzustellen, 
    dass es nur alphanumerische Zeichen und Leerzeichen enthält.
    '''
    header_value = request.args.get('header')

    if not header_value:
        return jsonify({"error": "Header value is missing. Please provide it as a query parameter, e.g., /parse_header?header=YourValue"}), 400

    # Regex to ensure only alphanumeric characters and spaces are allowed
    # ^ : start of string
    # [a-zA-Z0-9 ]+ : one or more alphanumeric characters or spaces
    # $ : end of string
    header_pattern = re.compile(r"^[a-zA-Z0-9 ]+$")

    if header_pattern.fullmatch(header_value):
        return jsonify({
            "status": "success",
            "message": "Header format is valid.",
            "parsed_header": header_value
        }), 200
    else:
        return jsonify({
            "status": "error",
            "message": "Header format is invalid. It must only contain alphanumeric characters and spaces."
        }), 400

if __name__ == '__main__':
    app.run(debug=True)
