import yaml

def load_yaml_config(config_data):
    '''
    Bir YAML dizesinden yapılandırma yükler.

    Fonksiyon, nesne örneklemesini önlemek için açık '!!python' etiketini kontrol eder.
    '''
    # Custom constructor to disallow !!python tags
    class SafeLoader(yaml.SafeLoader):
        def construct_mapping(self, node, deep=False):
            if node.tag and node.tag.startswith('!!python'):
                raise yaml.YAMLError("!!python tagları kullanılamaz.")
            return super().construct_mapping(node, deep)

        def construct_sequence(self, node, deep=False):
            if node.tag and node.tag.startswith('!!python'):
                raise yaml.YAMLError("!!python tagları kullanılamaz.")
            return super().construct_sequence(node, deep)

